import numpy as np

def bootstrap_indices(n, seed):
    rng = np.random.default_rng(seed)
    return rng.integers(0, n, size=n)

def fraction_unique(n, seed):
    idx = bootstrap_indices(n, seed)
    return len(np.unique(idx)) / n

